import {
  inMemoryWorkflowToFileFormat
} from "./packager-tool-e8td7b01.js";
import {
  logger
} from "./packager-tool-79gws1zn.js";

// ../flow-tool/src/utils/write-resolved-flow.ts
async function writeResolvedFlow(fs, dir, name, workflow) {
  const resolvedFileFormat = inMemoryWorkflowToFileFormat(workflow);
  const resolvedPath = fs.path.join(dir, `${name}.flow.resolved`);
  await fs.writeFile(resolvedPath, JSON.stringify(resolvedFileFormat, null, 2));
  logger.info(`Resolved flow written to ${resolvedPath}`);
}

export { writeResolvedFlow };

